// ===== FEATURE 3: Dark Mode toggle — behaviour (darkmode.js) =====
// Integrate: <script src="darkmode.js"></script> before </body>.
// Navbar button HTML snippet (paste inside .nav-inner, next to nav links):
//   <button id="darkModeToggle" class="dark-toggle" aria-label="Toggle theme">🌙</button>

(function(){
  const KEY = "anwaardigital-theme";

  function applyTheme(){
    const light = localStorage.getItem(KEY) === "light";
    document.body.classList.toggle("light-mode", light);
    const btn = document.getElementById("darkModeToggle");
    if(btn) btn.textContent = light ? "☀️" : "🌙";
  }

  document.addEventListener("DOMContentLoaded", function(){
    applyTheme();
    const btn = document.getElementById("darkModeToggle");
    if(btn){
      btn.addEventListener("click", function(){
        const light = document.body.classList.toggle("light-mode");
        localStorage.setItem(KEY, light ? "light" : "dark");
        btn.textContent = light ? "☀️" : "🌙";
      });
    }
  });
})();

/* about-img embedded fallback (images/ missing in repo) */
document.addEventListener('DOMContentLoaded',function(){
  var sel='img[src="images/about-islamic.jpg"]';
  var im=document.querySelector(sel);
  if(!im)return;
  var uri='data:image/jpeg;base64,';
  im.addEventListener('error',function h(){im.removeEventListener('error',h);im.src=uri;});
  if(im.complete&&im.naturalWidth===0){im.src=uri;}
});
